import numpy as np

def perceptron(X, y, epochs=50, eta=1.0):
    w = np.zeros(X.shape[1]); b = 0.0
    for _ in range(epochs):
        errors = 0
        for xi, yi in zip(X, y):
            if yi * (w @ xi + b) <= 0:          # only mistakes update
                w += eta * yi * xi
                b += eta * yi
                errors += 1
        if errors == 0:
            break                                # separated; nothing left to fix
    return w, b
